const test = require('node:test');
const assert = require('node:assert/strict');
const { calendarDate } = require('../src/calendar-label.cjs');

test("the requested zone determines the local calendar date", () => {
  assert.deepEqual(calendarDate('2026-01-01T00:30:00.000Z', 'America/New_York'), {year: 2025, month: 12, day: 31});
  assert.deepEqual(calendarDate('2026-03-31T16:15:00.000Z', 'Asia/Tokyo'), {year: 2026, month: 4, day: 1});
  assert.deepEqual(calendarDate('2026-01-01T00:30:00.000Z', 'UTC'), {year: 2026, month: 1, day: 1});
});

test("default Date components are year month and day", () => {
  assert.deepEqual(calendarDate('2024-02-29T12:00:00.000Z', 'UTC'), {year: 2024, month: 2, day: 29});
  assert.throws(() => calendarDate('2026-01-01T00:30:00.000Z', 'Invalid/Port'), RangeError);
});

